public class UnitTest : TestBase
{
    [Fact]
    public void FieldRoundtrip_Works()
    {
        var model = new Unit
        {
            Cadence = Cadence.Annual,
            ItemID = "item_id",
            LicenseAllocations =
            [
                new()
                {
                    Amount = "amount",
                    Currency = "currency",
